const API_BASE_URL = 'https://jsonplaceholder.typicode.com'

export interface Post {
  userId: number
  id: number
  title: string
  body: string
}

export interface PostComment {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

async function fetchJson<T>(path: string): Promise<T> {
  const res = await fetch(`${API_BASE_URL}${path}`)

  if (!res.ok) {
    throw new Error(`GET ${path} failed with status ${res.status}`)
  }

  return (await res.json()) as T
}

export function getPosts(limit?: number): Promise<Post[]> {
  return fetchJson<Post[]>(limit ? `/posts?_limit=${limit}` : '/posts')
}

export function getPost(id: string): Promise<Post> {
  return fetchJson<Post>(`/posts/${id}`)
}

export function getPostComments(id: string): Promise<PostComment[]> {
  return fetchJson<PostComment[]>(`/posts/${id}/comments`)
}

