/** Shapes returned by the `/api/posts` Route Handlers. */
export interface ApiPost {
  id: number
  title: string
  content: string
}

export interface CreatedApiPost extends ApiPost {
  createdAt: string
}

export interface UpdatedApiPost extends ApiPost {
  updatedAt: string
}

