import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import { getPost, getPostComments, getPosts } from '@/lib/posts'
import type { Post, PostComment } from '@/lib/posts'

/** Was `getStaticProps`' `revalidate: 300`. */
export const revalidate = 300

/**
 * Replaces `fallback: 'blocking'`: ids outside `generateStaticParams` are
 * rendered on demand on first request and then cached.
 */
export const dynamicParams = true

/** Was `getStaticPaths`. */
export async function generateStaticParams() {
  const posts = await getPosts()

  return posts.slice(0, 10).map((post) => ({ id: String(post.id) }))
}

interface PostPageData {
  post: Post
  comments: PostComment[]
}

/**
 * Replaces `return { notFound: true }`. The `fetch` calls are memoized per
 * request, so calling this from both `generateMetadata` and the page itself
 * does not double-fetch.
 */
async function loadPost(id: string): Promise<PostPageData> {
  try {
    const [post, comments] = await Promise.all([
      getPost(id),
      getPostComments(id),
    ])

    return { post, comments }
  } catch {
    notFound()
  }
}

export async function generateMetadata({
  params,
}: PageProps<'/blog/[id]'>): Promise<Metadata> {
  const { id } = await params
  const { post } = await loadPost(id)
  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: { title: post.title, description },
  }
}

export default async function BlogPostPage({ params }: PageProps<'/blog/[id]'>) {
  const { id } = await params
  const { post, comments } = await loadPost(id)

  return (
    <article>
      <BackButton>← Back</BackButton>
      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

