import { useEffect } from 'react'

interface ErrorProps {
  error: Error & { digest?: string }
  /** Re-renders the segment after a failure. Supersedes the old `reset` prop. */
  retry: () => void
}

/**
 * Replaces `pages/_error.js`. There is no `statusCode` to read anymore: 404s
 * are handled by `not-found.tsx`, and this boundary catches runtime errors
 * thrown while rendering a route.
 */
export default function Error({ error, retry }: ErrorProps) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <>
      <title>Error - My Blog</title>

      <div className="error-page">
        <h1>An error occurred</h1>
        <p>Sorry, something went wrong.</p>
        <button type="button" onClick={() => retry()}>
          Try again
        </button>
      </div>
    </>
  )
}

