import { parseApiPostInput } from '@/lib/api-posts'
import type { ApiError, ApiPost, CreatedApiPost } from '@/lib/api-posts'

/**
 * Was `pages/api/posts/index.js`. Route Handlers export one function per HTTP
 * method instead of switching on `req.method`, and Next.js answers any other
 * method with `405 Method Not Allowed` automatically — so the old explicit
 * `Allow` header / 405 branch is gone.
 */
export async function GET(): Promise<Response> {
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return Response.json(posts)
}

export async function POST(request: Request): Promise<Response> {
  const { title, content } = await parseApiPostInput(request)

  if (!title || !content) {
    const error: ApiError = { error: 'Title and content are required' }

    return Response.json(error, { status: 400 })
  }

  const newPost: CreatedApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}

