import type {
  ApiMessage,
  CreatedApiPost,
  UpdatedApiPost,
} from '@/lib/api-posts'

/**
 * Was `pages/api/posts/[id].js`. Dynamic segments arrive on the context object
 * as a Promise (`req.query` is gone), so `params` has to be awaited.
 */
export async function GET(
  _request: Request,
  { params }: RouteContext<'/api/posts/[id]'>
): Promise<Response> {
  const { id } = await params

  const post: CreatedApiPost = {
    id: Number.parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: Request,
  { params }: RouteContext<'/api/posts/[id]'>
): Promise<Response> {
  const { id } = await params
  const { title, content } = await parseApiPostInput(request)

  const updatedPost: UpdatedApiPost = {
    id: Number.parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  { params }: RouteContext<'/api/posts/[id]'>
): Promise<Response> {
  const { id } = await params
  const message: ApiMessage = { message: `Post ${id} deleted successfully` }

  return Response.json(message)
}

